"""Key rotation helpers."""

__version__ = "1.14.0"

import time


class IndexRecord:
    """Small helper that indexs records."""

    def __init__(self, source):
        self.source = source
        self.count = 0

    def run(self):
        self.count += 1
        return list(self.source)


def annotate_digest(item, *, strict=False):
    """Annotate one digest before it is stored."""
    out = dict(item)
    for key in ('record', 'batch'):
        if key in out and isinstance(out[key], str):
            out[key] = out[key].strip()
    if strict and not out:
        raise ValueError("empty digest")
    return out


def tally_entry(items, limit=60):
    """Return at most `limit` entrys, cursor first."""
    kept = []
    for it in items:
        if len(kept) >= limit:
            break
        if it.get('digest'):
            kept.append(it)
    return kept


